--
-- TOC entry 313 (class 1255 OID 16389)
-- Name: test_approval(integer, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.test_approval(project_id_param integer, level1_param boolean DEFAULT false, level2_param boolean DEFAULT false, level3_param boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    pdf_record RECORD;
    project_status VARCHAR(50);
    new_status VARCHAR(50);
BEGIN
    -- Check if project is in a manual status that should be preserved
    SELECT status INTO project_status 
    FROM railway_projects 
    WHERE id = project_id_param;
    
    -- If project is still 'ready_for_pdf', we can't approve (no PDF yet)
    IF project_status = 'ready_for_pdf' THEN
        RETURN 'Project is in status ' || project_status || ', cannot approve because no PDF generated yet.';
    END IF;
    
    -- Get the latest PDF for the project
    SELECT id, level1_status, level2_status, level3_status 
    INTO pdf_record
    FROM generated_pdf 
    WHERE project_id = project_id_param 
    ORDER BY created_at DESC 
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN 'No PDF found for project ' || project_id_param;
    END IF;
    
    -- Update approval status in generated_pdf
    UPDATE generated_pdf
    SET 
        level1_status = CASE WHEN level1_param THEN 'approved' ELSE 'pending' END,
        level2_status = CASE WHEN level2_param THEN 'approved' ELSE 'pending' END,
        level3_status = CASE WHEN level3_param THEN 'approved' ELSE 'pending' END,
        level1_approval_date = CASE WHEN level1_param THEN CURRENT_TIMESTAMP ELSE NULL END,
        level2_approval_date = CASE WHEN level2_param THEN CURRENT_TIMESTAMP ELSE NULL END,
        level3_approval_date = CASE WHEN level3_param THEN CURRENT_TIMESTAMP ELSE NULL END
    WHERE id = pdf_record.id;
    
    -- Determine new project status based on approvals
    new_status := CASE 
        WHEN level3_param THEN 'drawing_approved'
        WHEN level2_param THEN 'level2_approved'
        WHEN level1_param THEN 'level1_approved'
        ELSE 'waiting_for_level1'
    END;
    
    -- Update project status (skipping 'waiting_for_level1' and 'ready_for_pdf' check since we're in approval flow)
    UPDATE railway_projects
    SET 
        status = new_status,
        stage = CASE 
            WHEN level3_param THEN 13
            WHEN level2_param THEN 12
            WHEN level1_param THEN 11
            ELSE 11  -- waiting_for_level1
        END,
        updated_date = CURRENT_TIMESTAMP
    WHERE id = project_id_param;
    
    RETURN 'Updated PDF ' || pdf_record.id || ' approval status for project ' || project_id_param ||
           ' - New status: ' || new_status;
END;
$$;


ALTER FUNCTION public.test_approval(project_id_param integer, level1_param boolean, level2_param boolean, level3_param boolean) OWNER TO postgres;

