-- Name: update_project_junction_status(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_project_junction_status(p_project_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- Junctions WITH cables
    UPDATE junction_box jb
    SET status = CASE
        WHEN exp.expected_terminals = 0 THEN 3
        WHEN (act.actual_terminals * 100.0 / exp.expected_terminals) >= 95 THEN 3
        ELSE 2
    END
    FROM
        (
            SELECT
                c.junction_box,
                COALESCE(SUM(
                    CASE
                        WHEN c.terminal ~ '^[0-9]+$' THEN c.terminal::INT
                        ELSE 0
                    END
                ), 0) AS expected_terminals
            FROM cable c
            WHERE c.project_id = p_project_id
            GROUP BY c.junction_box
        ) exp
        LEFT JOIN
        (
            SELECT
                c.junction_box,
                COUNT(t.id) AS actual_terminals
            FROM cable c
            LEFT JOIN terminal t
                ON t.cable_id = c.cable_id
               AND t.project_id = c.project_id
            WHERE c.project_id = p_project_id
            GROUP BY c.junction_box
        ) act
        ON act.junction_box = exp.junction_box
    WHERE jb.project_id = p_project_id
      AND jb.junction_id = exp.junction_box;

    -- Junctions WITHOUT cables
    UPDATE junction_box jb
    SET status = 1
    WHERE jb.project_id = p_project_id
      AND NOT EXISTS (
          SELECT 1
          FROM cable c
          WHERE c.project_id = p_project_id
            AND c.junction_box = jb.junction_id
      );
END;
$_$;


ALTER FUNCTION public.update_project_junction_status(p_project_id integer) OWNER TO postgres;

