-- TOC entry 317 (class 1255 OID 16393)
-- Name: update_project_stage_auto(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_project_stage_auto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
    project_id_val INTEGER;
    highest_stage INTEGER := 0;
    new_status VARCHAR(50);
    pdf_approval_status RECORD;
BEGIN
    -- Get project ID from the new/updated record
    IF TG_OP = 'DELETE' THEN
        project_id_val := OLD.project_id;
    ELSE
        project_id_val := NEW.project_id;
    END IF;
    
    -- FIRST: Check if the project is currently marked as 'ready_for_pdf' OR 'preview'
    -- If yes, keep it at that status and stage
    IF EXISTS (
        SELECT 1 FROM railway_projects 
        WHERE id = project_id_val AND status IN ('ready_for_pdf', 'preview')
    ) THEN
        -- Keep the project as 'ready_for_pdf' or 'preview' and don't change anything
        RETURN NULL;
    END IF;
    
    -- Check if there's a generated PDF and its approval status
    SELECT 
        level1_status,
        level2_status,
        level3_status
    INTO pdf_approval_status
    FROM generated_pdf 
    WHERE project_id = project_id_val 
    ORDER BY created_at DESC 
    LIMIT 1;
    
    -- If PDF exists, check approval status first
    IF FOUND THEN
        -- Check approval levels in sequence (highest to lowest)
        IF pdf_approval_status.level3_status = 'approved' THEN
            highest_stage := 13;  -- Level 3 Approved
        ELSIF pdf_approval_status.level2_status = 'approved' THEN
            highest_stage := 12;  -- Level 2 Approved
        ELSIF pdf_approval_status.level1_status = 'approved' THEN
            highest_stage := 11;  -- Level 1 Approved
        ELSE
            highest_stage := 10;  -- PDF Generated but not approved
        END IF;
    END IF;
    
    -- If no PDF or PDF is at stage 10, check for other data
    IF highest_stage <= 10 THEN
        -- Find the HIGHEST stage with data (stages 1-9)
        IF EXISTS (SELECT 1 FROM cable_box WHERE project_id = project_id_val) THEN
            highest_stage := 9;  -- Cable Box
        ELSIF EXISTS (SELECT 1 FROM resistor_table WHERE project_id = project_id_val) THEN
            highest_stage := 8;  -- Resistor Table
        ELSIF EXISTS (SELECT 1 FROM choke_table WHERE project_id = project_id_val) THEN
            highest_stage := 7;  -- Choke Table
        ELSIF EXISTS (SELECT 1 FROM group_table WHERE project_id = project_id_val) THEN
            highest_stage := 6;  -- Groups
        ELSIF EXISTS (SELECT 1 FROM terminal_header WHERE project_id = project_id_val) THEN
            highest_stage := 5;  -- Headers
        ELSIF EXISTS (SELECT 1 FROM terminal WHERE project_id = project_id_val) THEN
            highest_stage := 4;  -- Terminals
        ELSIF EXISTS (SELECT 1 FROM cable WHERE project_id = project_id_val) THEN
            highest_stage := 3;  -- Cables
        ELSIF EXISTS (SELECT 1 FROM junction_box WHERE project_id = project_id_val) THEN
            highest_stage := 2;  -- Locations
        ELSIF EXISTS (SELECT 1 FROM station_drawing WHERE project_id = project_id_val) THEN
            highest_stage := 1;  -- Station Info
        END IF;
    END IF;
    
    -- Determine status based on stage
    new_status := CASE 
        WHEN highest_stage = 0 THEN 'drawing_not_started'
        WHEN highest_stage = 1 THEN 'drawing_in_progress'
        WHEN highest_stage BETWEEN 2 AND 9 THEN 'drawing_in_progress'
        WHEN highest_stage = 10 THEN 'drawing_complete'
        WHEN highest_stage = 11 THEN 'level1_approved'
        WHEN highest_stage = 12 THEN 'level2_approved'
        WHEN highest_stage = 13 THEN 'drawing_approved'
        ELSE 'drawing_in_progress'
    END;
    
    -- Update the project's stage and status
    UPDATE railway_projects
    SET 
        stage = highest_stage,
        status = new_status,
        updated_date = CURRENT_TIMESTAMP
    WHERE id = project_id_val;
    
    -- Debug output
    RAISE NOTICE 'Updated project %: stage to %, status to %', 
        project_id_val, highest_stage, new_status;
    
    RETURN NULL;
END;$$;


ALTER FUNCTION public.update_project_stage_auto() OWNER TO postgres;

--
-- TOC entry 318 (class 1255 OID 16394)
-- Name: update_project_stage_auto_for_id(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_project_stage_auto_for_id(project_id_param integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    highest_stage INTEGER := 0;
    old_stage INTEGER;
    new_status VARCHAR(50);
    pdf_approval_status RECORD;
    has_complete_data BOOLEAN;
BEGIN
    -- Get current stage
    SELECT stage INTO old_stage FROM railway_projects WHERE id = project_id_param;
    
    -- Check if project has complete data (all sheets up to cable_box)
    SELECT EXISTS (
        SELECT 1 FROM station_drawing WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM junction_box WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM cable WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM terminal WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM group_table WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM terminal_header WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM choke_table WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM resistor_table WHERE project_id = project_id_param
        UNION ALL
        SELECT 1 FROM cable_box WHERE project_id = project_id_param
    ) INTO has_complete_data;
    
    -- Check if there's a generated PDF and its approval status
    SELECT 
        level1_status,
        level2_status,
        level3_status
    INTO pdf_approval_status
    FROM generated_pdf 
    WHERE project_id = project_id_param 
    ORDER BY created_at DESC 
    LIMIT 1;
    
    -- If PDF exists, check approval status first
    IF FOUND THEN
        -- Check approval levels in sequence (highest to lowest)
        IF pdf_approval_status.level3_status = 'approved' THEN
            highest_stage := 13;  -- Level 3 Approved
        ELSIF pdf_approval_status.level2_status = 'approved' THEN
            highest_stage := 12;  -- Level 2 Approved
        ELSIF pdf_approval_status.level1_status = 'approved' THEN
            highest_stage := 11;  -- Level 1 Approved
        ELSE
            -- PDF exists but not approved
            -- CRITICAL FIX: If project has complete data AND PDF exists, it's waiting for level1 (stage 11)
            -- Otherwise, it's ready for PDF generation (stage 10)
            IF has_complete_data THEN
                highest_stage := 11;  -- All data complete, PDF waiting for level1 approval
            ELSE
                highest_stage := 10;  -- PDF generated but data may be incomplete
            END IF;
        END IF;
    END IF;
    
    -- If no PDF or PDF is at stage 10/11 (and needs data check), check for other data
    IF highest_stage <= 11 THEN
        -- Find the HIGHEST stage with data (stages 1-9)
        IF EXISTS (SELECT 1 FROM cable_box WHERE project_id = project_id_param) THEN
            highest_stage := 9;
        ELSIF EXISTS (SELECT 1 FROM resistor_table WHERE project_id = project_id_param) THEN
            highest_stage := 8;
        ELSIF EXISTS (SELECT 1 FROM choke_table WHERE project_id = project_id_param) THEN
            highest_stage := 7;
        ELSIF EXISTS (SELECT 1 FROM group_table WHERE project_id = project_id_param) THEN
            highest_stage := 6;
        ELSIF EXISTS (SELECT 1 FROM terminal_header WHERE project_id = project_id_param) THEN
            highest_stage := 5;
        ELSIF EXISTS (SELECT 1 FROM terminal WHERE project_id = project_id_param) THEN
            highest_stage := 4;
        ELSIF EXISTS (SELECT 1 FROM cable WHERE project_id = project_id_param) THEN
            highest_stage := 3;
        ELSIF EXISTS (SELECT 1 FROM junction_box WHERE project_id = project_id_param) THEN
            highest_stage := 2;
        ELSIF EXISTS (SELECT 1 FROM station_drawing WHERE project_id = project_id_param) THEN
            highest_stage := 1;
        END IF;
    END IF;
    
    -- Determine status based on stage
    new_status := CASE 
        WHEN highest_stage = 0 THEN 'drawing_not_started'
        WHEN highest_stage = 1 THEN 'drawing_in_progress'
        WHEN highest_stage BETWEEN 2 AND 9 THEN 'drawing_in_progress'
        WHEN highest_stage = 10 THEN 'ready_for_pdf'
        WHEN highest_stage = 11 THEN 'waiting_for_level1'
        WHEN highest_stage = 12 THEN 'level1_approved'
        WHEN highest_stage = 13 THEN 'level2_approved'
        WHEN highest_stage = 14 THEN 'drawing_approved'
        ELSE 'drawing_in_progress'
    END;
    
    -- Update the project
    UPDATE railway_projects
    SET 
        stage = highest_stage,
        status = new_status,
        updated_date = CURRENT_TIMESTAMP
    WHERE id = project_id_param;
    
    RETURN 'Project ' || project_id_param || ': stage ' || 
           COALESCE(old_stage::text, 'NULL') || ' -> ' || 
           highest_stage::text || ', status: ' || new_status;
END;
$$;


ALTER FUNCTION public.update_project_stage_auto_for_id(project_id_param integer) OWNER TO postgres;

--
-- TOC entry 319 (class 1255 OID 16395)
-- Name: update_project_status_from_stage(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_project_status_from_stage(project_id_param integer) RETURNS text
    LANGUAGE plpgsql
    AS $$DECLARE
    project_stage INTEGER;
    new_status VARCHAR(50);
    old_status VARCHAR(50);
    project_status VARCHAR(50);
BEGIN
    -- Get current stage and status
    SELECT stage, status INTO project_stage, old_status
    FROM railway_projects 
    WHERE id = project_id_param;
    
    IF NOT FOUND THEN
        RETURN 'Project not found';
    END IF;
    
    -- Check if status is already 'preview' - don't change it
    SELECT status INTO project_status
    FROM railway_projects 
    WHERE id = project_id_param;
    
    -- If status is 'preview', don't change it
    IF project_status = 'preview' THEN
        RETURN 'Project ' || project_id_param || ' status remains as preview (manually set)';
    END IF;
    
    -- Determine new status based on stage
    new_status := CASE 
        WHEN project_stage IS NULL OR project_stage = 0 THEN 'drawing_not_started'
        WHEN project_stage = 1 THEN 'drawing_in_progress'
        WHEN project_stage BETWEEN 2 AND 9 THEN 'drawing_in_progress'
        WHEN project_stage = 10 THEN 'drawing_complete'
        WHEN project_stage = 11 THEN 'level1_approved'
        WHEN project_stage = 12 THEN 'level2_approved'
        WHEN project_stage = 13 THEN 'drawing_approved'
        ELSE old_status  -- Keep existing if stage doesn't match known values
    END;
    
    -- Update if status has changed
    IF new_status != old_status THEN
        UPDATE railway_projects
        SET 
            status = new_status,
            updated_date = CURRENT_TIMESTAMP
        WHERE id = project_id_param;
        
        RETURN 'Updated project ' || project_id_param || ' status: ' || old_status || ' -> ' || new_status;
    ELSE
        RETURN 'Project ' || project_id_param || ' status unchanged: ' || old_status;
    END IF;
END;$$;


ALTER FUNCTION public.update_project_status_from_stage(project_id_param integer) OWNER TO postgres;

