--
-- TOC entry 273 (class 1259 OID 16673)
-- Name: project_progress_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.project_progress_summary AS
 SELECT id,
    name,
    stage,
        CASE
            WHEN (stage = 0) THEN 'No data'::text
            WHEN (stage = 1) THEN 'Station Info'::text
            WHEN (stage = 2) THEN 'Locations'::text
            WHEN (stage = 3) THEN 'Cables'::text
            WHEN (stage = 4) THEN 'Terminals'::text
            WHEN (stage = 5) THEN 'Headers'::text
            WHEN (stage = 6) THEN 'Groups'::text
            WHEN (stage = 7) THEN 'Choke Table'::text
            WHEN (stage = 8) THEN 'Resistor Table'::text
            WHEN (stage = 9) THEN 'Cable Box'::text
            WHEN (stage = 10) THEN 'PDF Generated'::text
            ELSE 'Unknown'::text
        END AS stage_display,
    updated_date AS last_updated,
    ( SELECT count(*) AS count
           FROM public.station_drawing
          WHERE (station_drawing.project_id = rp.id)) AS station_count,
    ( SELECT count(*) AS count
           FROM public.junction_box
          WHERE (junction_box.project_id = rp.id)) AS junction_count,
    ( SELECT count(*) AS count
           FROM public.cable
          WHERE (cable.project_id = rp.id)) AS cable_count,
    ( SELECT count(*) AS count
           FROM public.terminal
          WHERE (terminal.project_id = rp.id)) AS terminal_count,
    ( SELECT count(*) AS count
           FROM public.terminal_header
          WHERE (terminal_header.project_id = rp.id)) AS header_count,
    ( SELECT count(*) AS count
           FROM public.group_table
          WHERE (group_table.project_id = rp.id)) AS group_count,
    ( SELECT count(*) AS count
           FROM public.choke_table
          WHERE (choke_table.project_id = rp.id)) AS choke_count,
    ( SELECT count(*) AS count
           FROM public.resistor_table
          WHERE (resistor_table.project_id = rp.id)) AS resistor_count,
    ( SELECT count(*) AS count
           FROM public.cable_box
          WHERE (cable_box.project_id = rp.id)) AS cable_box_count,
    ( SELECT count(*) AS count
           FROM public.generated_pdf
          WHERE (generated_pdf.project_id = rp.id)) AS pdf_count
   FROM public.railway_projects rp
  ORDER BY id;


ALTER VIEW public.project_progress_summary OWNER TO postgres;

--
-- TOC entry 274 (class 1259 OID 16678)
-- Name: project_stage_monitor; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.project_stage_monitor AS
 SELECT id,
    name,
    stage,
        CASE stage
            WHEN 0 THEN 'No data'::text
            WHEN 1 THEN 'Station Info'::text
            WHEN 2 THEN 'Locations'::text
            WHEN 3 THEN 'Cables'::text
            WHEN 4 THEN 'Terminals'::text
            WHEN 5 THEN 'Headers'::text
            WHEN 6 THEN 'Groups'::text
            WHEN 7 THEN 'Choke Table'::text
            WHEN 8 THEN 'Resistor Table'::text
            WHEN 9 THEN 'Cable Box'::text
            WHEN 10 THEN 'PDF Generated'::text
            WHEN 11 THEN 'Level 1 Approved'::text
            WHEN 12 THEN 'Level 2 Approved'::text
            WHEN 13 THEN 'Level 3 Approved'::text
            ELSE 'Unknown'::text
        END AS stage_display,
    status,
        CASE stage
            WHEN 0 THEN 'drawing_not_started'::character varying
            WHEN 1 THEN 'drawing_in_progress'::character varying
            WHEN 2 THEN 'drawing_in_progress'::character varying
            WHEN 3 THEN 'drawing_in_progress'::character varying
            WHEN 4 THEN 'drawing_in_progress'::character varying
            WHEN 5 THEN 'drawing_in_progress'::character varying
            WHEN 6 THEN 'drawing_in_progress'::character varying
            WHEN 7 THEN 'drawing_in_progress'::character varying
            WHEN 8 THEN 'drawing_in_progress'::character varying
            WHEN 9 THEN 'drawing_in_progress'::character varying
            WHEN 10 THEN 'drawing_complete'::character varying
            WHEN 11 THEN 'level1_approved'::character varying
            WHEN 12 THEN 'level2_approved'::character varying
            WHEN 13 THEN 'drawing_approved'::character varying
            ELSE status
        END AS expected_status,
    updated_date AS last_updated,
    ( SELECT max(generated_pdf.created_at) AS max
           FROM public.generated_pdf
          WHERE (generated_pdf.project_id = rp.id)) AS pdf_date,
    ( SELECT generated_pdf.level1_status
           FROM public.generated_pdf
          WHERE (generated_pdf.project_id = rp.id)
          ORDER BY generated_pdf.created_at DESC
         LIMIT 1) AS level1_status,
    ( SELECT generated_pdf.level2_status
           FROM public.generated_pdf
          WHERE (generated_pdf.project_id = rp.id)
          ORDER BY generated_pdf.created_at DESC
         LIMIT 1) AS level2_status,
    ( SELECT generated_pdf.level3_status
           FROM public.generated_pdf
          WHERE (generated_pdf.project_id = rp.id)
          ORDER BY generated_pdf.created_at DESC
         LIMIT 1) AS level3_status
   FROM public.railway_projects rp
  ORDER BY id;


ALTER VIEW public.project_stage_monitor OWNER TO postgres;

